#!/usr/bin/env python3
"""Draft responses for the reviewer comments that have none yet, and update the drafted ones whose numbers changed,
as tracked purple insertions with a comment explaining the basis. Usage: python3 apply_reviewer_responses.py <unpacked_dir>"""
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from docx_edit import Doc
import ms_numbers
from ms_numbers import sp, fmt

N = ms_numbers.load(); r5 = N["r5"]
def r5get(prefix):
    for k, v in r5.items():
        if k.startswith(prefix): return v
    return None
d = Doc(sys.argv[1]); d.dry = os.environ.get("DRY") == "1"
AI = "[AI draft] "

def I(anchor, text, why):
    return d.insert_after(d.one(anchor), text, AI + why)
def R(anchor, old, new, why):
    d.replace(d.one(anchor), old, new, AI + why)

NOTE = "Draft response written by the AI assistant from the rerun results; please check the wording and the numbers against manuscript/RESULTS_NUMBERS.md before use."

# ---------------- Reviewer 1 ----------------
I("Odniesc sie do cooccurrence",
  "We thank the Reviewer. We now define the term operationally at its first use in the Introduction and in the Results, and in the Methods. For features X1 (base) and X2 (contributing) and the disease label Y, a pair is called synergistic when the joint information gain I(X1, X2; Y) exceeds the 1D information gain of the base feature by a statistically significant margin (chi-squared test on the added information gain, Bonferroni-corrected over all feature pairs) and exceeds the 1D information gain of either feature alone. In other words, the two features together carry information about the disease label that neither carries alone. We also state explicitly that this is a statistical statement about a jointly informative co-occurrence pattern: it does not imply causality or any particular biological relationship between the two features, and we have removed wording that suggested otherwise."
  + (f" To address the related question of whether such pairs are merely additive (Reviewer 2, comment 2), we now also report the interaction information I(X1, X2; Y) − I(X1; Y) − I(X2; Y) for every retained pair: it is positive for {r5get('taxa: consensus pairs with positive interaction information').split(' of')[0]} (taxa), {r5get('functions: consensus pairs with positive interaction information').split(' of')[0]} (functions) and {r5get('combined: consensus pairs with positive interaction information').split(' of')[0]} (combined) of the consensus pair–fold entries." if r5get('taxa: consensus pairs with positive interaction information') else ""),
  NOTE + " Your note asked to relate synergy to co-occurrence without causal information; that sentence is included.")
I("Moje najwazniejsze moga sie nie pokryc z innymi narzedziami",
  f"We agree that a benchmark against alternative approaches is informative, and we have added two analyses that address it within the scope of this study. First, for every stable pair we fitted cohort-adjusted logistic regression models to the pooled CRC cohorts and compared, by likelihood-ratio tests, the cohort-only, additive (both constituents) and interaction (constituents plus their product) models, the comparison suggested by Reviewer 2. "
  + (f"{r5get('Stable pairs informative beyond cohort membership').split('/')[0]} of the {N['n_stable']} stable pairs remained informative beyond cohort membership and {r5get('Stable pairs with a significant multiplicative interaction').split('/')[0]} showed a significant multiplicative interaction term (Benjamini–Hochberg q < 0.05; Supplementary Table 9). " if r5get('Stable pairs informative beyond cohort membership') else "")
  + "Second, we report the information-theoretic interaction information of every retained pair (response to comment 1). We have not benchmarked the framework against SHAP interaction values or against sparse multivariate classifiers, because these methods answer a different question: they attribute a fitted model's predictions to features or feature pairs, whereas our framework performs an exhaustive, model-free scan of all pairs for joint information about the label and then validates the retained pairs by held-out classification and per-cohort effect sizes. We now say this explicitly in the Introduction and Discussion, together with an acknowledgement of the existing multivariate and compositional approaches, and we state that pairs reported by such model-based methods would be expected to be a subset of the pairs scanned here. A systematic comparison across tools is a worthwhile follow-up study.",
  NOTE + " Your note: the top pairs of other tools may not coincide with ours but should be covered by MDFS; and the Daga heatmap. I did not run SHAP or GLM scans; the paragraph says so. If you want a real benchmark, the LRT in R5_reviewer_checks/stable_pairs_lrt.tsv can be extended to all consensus pairs.")
